class Solution {
    public int minOperations(int[] nums,int k){
        PriorityQueue<Long> heap=new PriorityQueue<>();
        for(int value:nums)heap.add((long)value);
        int operations=0;
        while(heap.peek()<k){
            long first=heap.poll(),second=heap.poll();
            heap.add(first*2+second);
            operations++;
        }
        return operations;
    }
}

code.kotlin:
class Solution {
    fun minOperations(nums:IntArray,k:Int):Int{
        val heap=java.util.PriorityQueue<Long>();
        for(value in nums)heap.add(value.toLong());
        var operations=0;
        while(heap.peek()<k.toLong()){
            val first=heap.poll();
            val second=heap.poll();
            heap.add(first*2+second);
            operations++
        };
        return operations
    }
}

